ted kitchen facility.","mobileDescription":"Dedicated shuddh kitchen","icon":"veg"},{"id":"shipping","title":"Pan-India Express","mobileTitle":"Pan-India","description":"Dispatched in 24 hrs to 26,000+ pin codes.","mobileDescription":"Dispatched in 24 hrs","icon":"shipping"}]'::jsonb) on conflict (page_key, section_key) do update set content=excluded.content;
